import{_ as e,c as a,a2 as o,o as p}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易无法预测！","description":"","frontmatter":{},"headers":[],"relativePath":"stock/不预测/交易无法预测.md","filePath":"stock/不预测/交易无法预测.md"}'),r={name:"stock/不预测/交易无法预测.md"};function s(n,t,c,i,_,d){return p(),a("div",null,t[0]||(t[0]=[o('<h1 id="交易无法预测" tabindex="-1">交易无法预测！ <a class="header-anchor" href="#交易无法预测" aria-label="Permalink to &quot;交易无法预测！&quot;">​</a></h1><p><strong>当你真正明白这一点的时候，所有的交易问题可以说全部解决了</strong>。现在是顶部，是不是，谁也不知道，但是感觉自己知道的人会怎么做了，感觉这里是顶部的人就会卖掉手中赢利的筹码，等待下跌，这个时候你的利润已经无法奔跑了。感觉这里不是顶部的人就会加码。亏损了就会告诉自己这里不是顶部，这只是暂时套牢而已。或许巨亏已经埋下种子。其实在任何时候说多空，都是一种概率，上涨以后下跌可以是一次调整，也可以是一次头部，这里有一个概率问题，上涨以后下跌调整的概率是相当大的，因为顶部只有一个，调整可以有无数次，也就是说在一次上涨以后的下跌中买入获利的概率远远大于亏损。这是技术分析的用途，利用概率得到利润。而不是技术分析演变成造神论，对于技术分析的使用者变成幻想交易者。</p><p>只有交易者真正明白了交易无法预测的时候，交易者将对多空没有任何思维概率，因为交易的无法预测，交易者首先考虑的第一件事情不是技术的对与错，概率的多和少，而是风险，因为每一笔交易都有可能是一笔亏损的交易，所以在下单的时候，亏损多少出局是交易者首先考虑的事情，因为交易者知道，交易是没有规律的，止损以后也许能暴涨，也许能暴跌，但是做为交易者无法控制，但是做为资金所有者，交易者可以控制风险。如果一个单子赢利以后，交易者同样也知道交易无法预测，所以哪里是顶根本不知道，只能跟着上帝走，但是交易者可以控制不把一个赢利的单子变成亏损。在没有到达一个止赢点以前，让利润奔跑吧。</p><p>交易没有对和错，千万不要认死理，很多人都在依靠感觉和技术相信自己可以分析市场，感觉市场，扯淡，找个黑猩猩掷飞镖概率都比预测高。</p><p>市场有没有趋势，没有，这个真的没有，趋势都是走出来以后你发现这是一个趋势了，当身在其中的时候，趋势如流水一般，可以在任何节点转折。在这个市场，分析和预测是次要的，最重要的是跟随和止损，把自己的心倒空，平静而且空灵，小单子跟随，到止损点平仓，跟对了，加码，拿住你的利润。市场会怎么走，只有上帝知道，所以把你的利润交给上帝来分配。但是市场充满风险，为了能长期和上帝分享利润，请一定要止损。</p><p>市场最不缺少的是机会，而缺少的是耐心。市场不会关门，它一直在为投资者敞开着，给有准备的投资者以机会，给盲目的投资者以教训！现在你可以问自己一个很现实的问题：我凭什么在股市中赚钱？如果你还没有一个具体的答案，那么可以说，即使你在股市中赚了第一桶金也都是浮云，终究还是会“还”给市场。因为你不知道它如何而来，它必然同样让你不知道如何而去。可以说，你的投资计划越明确、越具体，那么你就越有可能赢，也越有可能赢得更久。</p><p>交易是一个没有终点的过程，每一个交易者都要么在准备进场，要么在准备离场，在这种循环往复中不仅仅是枯燥和无味，更多的是对心理的摧残，由此形成的各种类似于想赢怕输的交易障碍才是交易中最难的，交易的过程最怕的就是决策的过程没有依据可以遵循，这也是对交易产生恐惧的根源。</p><p>唯一能做的就是尽量的依靠技术分析的可推测性（当然这种正确率是要打折扣的）形成一些偏向于程式化和公式化的交易依据（可以视作交易系统的雏形），这样最大好处是可以把交易决策过程中那种不安的心理状态变成一种数量化的选择过程。</p><p>当然这也还不是交易中最重要的，最重要的是要自己能想明白，你依据的是一种概率论的角度是审视这个市场并且决定交易策略，而是主观预判，你所使用的技术分析真正的意义是是丈量，而不是决策。</p>',9)]))}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
